    bool GameInfoShown;
    bool Term() { return g_frames >= g_stopAt; }
    void Frame() { ++g_frames; }
    bool Near() { return g_frames >= g_nearAt; }
    bool Clicked() { return g_frames >= g_clickAt; }
    void Show(const char* t) { ++g_shown; std::strcpy(g_text, t); }
    void Main()
    {
        Frame();
        if (Term()) return;
        while (!GameInfoShown) {
